So my `application` object could look like this:

```js
class Application {
  constructor(el) {
    this.root = el;
    this.el = el.querySelector('#app');

    this.routes = {};

    this.registerRoute('bookmarks', 'index');

    this.views = {
      index: new IndexView()
    };

    this.bookmarks = new Bookmarks();
    this.data = new Data(this.bookmarks);

    el.onclick = event => this.onClick(event);
  }

  onClick(event) {
    let link = event.target;
    // this handles internal routes but what about href="javascript:function()"?
  }

  /**
   * Register a route as a route key and path
   * 
   * A 'route key' is the actual key defined in the routes object. The path is what is expected
   * in `window.location.hash`, if a path starts with '/', it will be matched as the first
   * thing in the hash. 
   * 
   * Example: 
   * application.registerRoute('foo', '/foo');
   * application.registerRoute('bar', 'bar');
   * application.registerRoute('baz', 'baz/:id');
   * 
   * window.location.hash = '#/foo' => the route 'foo' will be matched
   * window.location.hash = '#bar' => the route 'bar' will be matched
   * window.location.hash = '#bar/1' => the route 'bar' will be matched
   * window.location.hash = '#baz' => no route will be matched
   * window.location.hash = '#baz/1' => the route 'baz' will be matched
   * window.location.hash = '#/foo/bar' => no route will be matched, unless another route was registered
   * for this.
   * window.location.hash = '#/bar/foo' => the route 'bar' will be matched, provided there is a route 
   * registered that does not have a leading '/' for bar.
   * window.location.hash = '#foo' => the route 'bar' will be matched
   * 
   * Essentially a '/'-prefixed route key is treated as exclusive, and a non-prefixed route key 
   * as a "fuzzy match".
   */
  registerRoute(key, path) {
    this.routes[key] = path;
  }

